'use strict';
const uxViews={};const uxSelections=new Map();let uxChatMessages=[],uxChatBusy=false,uxExportEntries=[];
const uxKinds={customers:['software_version'],submissions:['submission'],requirements:['requirement'],cases:['case','workflow_case'],sources:['document'],workflows:['workflow'],reports:['run','auto_job','workflow']};
function uxView(name){return uxViews[name]||(uxViews[name]={search:'',status:'all',fresh:'all',sort:'newest',visibility:'all',editing:false});}
function uxKey(kind,id){return kind+':'+id;}
function uxUnread(kind,id){return (state?.workspace?.unseen?.[kind]||[]).includes(id);}
function uxItems(view,items){const v=uxView(view),kind={requirements:'requirement',cases:'case',sources:'document',workflows:'workflow',customers:'software_version',submissions:'submission'}[view];return items.map((x,i)=>({x,i})).filter(({x})=>{const status=x.status||x.review_status||x.overall_status||x.phase||x.version_state||'';const fresh=uxUnread(x.workflow_id?'workflow_case':kind||'run',x.workflow_id?x.workflow_id+'|'+x.id:x.id);return !x.trashed_at&&(v.visibility==='all'||(v.visibility==='hidden')===!!x.hidden)&&(v.status==='all'||status===v.status)&&(v.fresh==='all'||(v.fresh==='new')===fresh)&&(!v.search||[x.title,x.name,x.case_name,x.version,x.criterion,x.customer?.company,x.project?.software,x.manufacturer_name,x.software,x.email,x.contact].some(t=>String(t||'').toLocaleLowerCase().includes(v.search.toLocaleLowerCase())));}).sort((a,b)=>v.sort==='title'?String(a.x.title||a.x.name||a.x.case_name||'').localeCompare(String(b.x.title||b.x.name||b.x.case_name||'')):v.sort==='visibility'?Number(!!a.x.hidden)-Number(!!b.x.hidden)||b.i-a.i:v.sort==='unread'?Number(uxUnread(b.x.workflow_id?'workflow_case':kind,b.x.workflow_id?b.x.workflow_id+'|'+b.x.id:b.x.id))-Number(uxUnread(a.x.workflow_id?'workflow_case':kind,a.x.workflow_id?a.x.workflow_id+'|'+a.x.id:a.x.id))||b.i-a.i:(v.sort==='oldest'?1:-1)*((Date.parse(a.x.created_at||a.x.reviewed_at||'')||a.i)-(Date.parse(b.x.created_at||b.x.reviewed_at||'')||b.i))).map(x=>x.x);}
function uxToolbar(view){const v=uxView(view),statuses={customers:['neu','in_pruefung','freigegeben','abgelehnt','erneut_pruefen'],submissions:['pending','approved','rejected'],requirements:['pending','approved','rejected'],cases:['pending','approved','rejected'],sources:['new_document','new_version','corrected','historical_version'],workflows:flowPhases,reports:['pass','fail','not_assessable','technical_error','completed','waiting_import']}[view]||[];const chosen=[...uxSelections.values()].filter(x=>(uxKinds[view]||[]).includes(x.kind));return `<div class="ux-toolbar" data-ux-view="${view}"><div class="ux-toolbar-left"><details class="ux-popover"><summary title="Filtern">${icon('filter')}<span>Filter</span>${v.status!=='all'||v.fresh!=='all'||v.visibility!=='all'||v.search?'<i class="ux-filter-active"></i>':''}</summary><form class="ux-filter-form" data-view="${view}"><div class="field"><label>Suchen</label><input name="search" value="${e(v.search)}" placeholder="Titel, Name oder Inhalt"></div><div class="field"><label>Sichtbarkeit</label><select name="visibility"><option value="all">Alle</option><option value="visible" ${v.visibility==='visible'?'selected':''}>Nur eingeblendete</option><option value="hidden" ${v.visibility==='hidden'?'selected':''}>Nur ausgeblendete</option></select></div><div class="field"><label>Status</label><select name="status"><option value="all">Alle</option>${statuses.map(s=>`<option value="${s}" ${s===v.status?'selected':''}>${e(labels[s]||flowNames[s]||s)}</option>`).join('')}</select></div>${['requirements','cases'].includes(view)?`<div class="field"><label>Gelesen / neu</label><select name="fresh"><option value="all">Alle</option><option value="new" ${v.fresh==='new'?'selected':''}>Nur neue</option><option value="read" ${v.fresh==='read'?'selected':''}>Nur gelesene</option></select></div>`:''}<div class="actions"><button class="btn primary small">Anwenden</button><button class="btn small" type="button" data-action="ux-reset" data-view="${view}">Zurücksetzen</button></div></form></details><label class="ux-sort">${icon('sort')}<span class="sr-only">Sortieren</span><select data-ux-sort="${view}" aria-label="Sortieren"><option value="newest" ${v.sort==='newest'?'selected':''}>Neueste zuerst</option><option value="oldest" ${v.sort==='oldest'?'selected':''}>Älteste zuerst</option><option value="title" ${v.sort==='title'?'selected':''}>Titel A–Z</option><option value="visibility" ${v.sort==='visibility'?'selected':''}>Eingeblendete zuerst</option>${['requirements','cases'].includes(view)?`<option value="unread" ${v.sort==='unread'?'selected':''}>Ungelesene zuerst</option>`:''}</select></label></div><div class="actions">${v.editing?`<label class="ux-select-all"><input type="checkbox" data-ux-all="${view}"> Alle sichtbaren</label><span class="ux-selection-count">${chosen.length} ausgewählt</span>${btn(icon('trash'),'ux-trash',`data-view="${view}" aria-label="Auswahl in den Papierkorb" title="In den Papierkorb"`,'icon-button')}${btn(icon('export'),'ux-export',`data-view="${view}" aria-label="Auswahl exportieren oder weiterleiten" title="Exportieren / weiterleiten"`,'icon-button')}`:''}${btn(icon(v.editing?'close':'edit')+'<span>'+e(v.editing?'Fertig':'Bearbeiten')+'</span>','ux-edit',`data-view="${view}"`,'small')}</div></div>`;}
function uxEntry(kind,id){const view=Object.keys(uxKinds).find(v=>uxKinds[v].includes(kind)&&uxView(v).editing);return `<span class="ux-entry-tools">${view?`<input type="checkbox" class="ux-checkbox" data-ux-kind="${kind}" data-ux-id="${e(id)}" aria-label="Eintrag auswählen" ${uxSelections.has(uxKey(kind,id))?'checked':''}>`:''}${uxUnread(kind,id)?'<span class="ux-new-dot" title="Neu · noch nicht geöffnet" aria-label="Neu"></span>':''}</span>`;}
function uxEnhance(root){
 for(const label of root.querySelectorAll('.field:has([data-case-group]) label'))label.dataset.userContent='';
 for(const card of root.querySelectorAll('.rule-card,.case-card,.document-card,.flow-cases>details,.ux-workflow-row,.package-row,tr[data-ux-id],section[data-ux-kind]')){
  let kind=card.dataset.uxKind,id=card.dataset.uxId;
  if(!id){const b=card.querySelector('[data-action="review"],[data-action="lib-revise"],[data-action="lib-document"],[data-action="lib-job"]');if(!b)continue;kind=b.dataset.kind||(b.dataset.action==='lib-document'?'document':b.dataset.action==='lib-job'?'auto_job':'requirement');id=b.dataset.id;}
  if(!id)continue;card.dataset.uxKind=kind;card.dataset.uxId=id;const item=kind==='workflow_case'?state.workflow.items.find(w=>w.id===id.split('|')[0]):(kind==='manufacturer'?state.customers.manufacturers:kind==='software_version'?state.customers.versions:kind==='submission'?state.customers.submissions:kind==='document'?state.documents:kind==='requirement'?state.requirements:kind==='case'?state.cases:kind==='workflow'?state.workflow.items:kind==='run'?state.runs:state.automation.jobs).find(x=>x.id===id);card.classList.toggle('ux-hidden',!!item?.hidden);
  if(kind==='document'&&!card.querySelector('[data-action="ux-hide"]'))card.querySelector('.actions')?.insertAdjacentHTML('beforeend',btn(icon(item.hidden?'eye':'eye-off'),'ux-hide',`data-kind="document" data-id="${e(id)}" data-hidden="${!item.hidden}" title="${item.hidden?'Einblenden':'Ausblenden'}" aria-label="${item.hidden?'Einblenden':'Ausblenden'}"`,'small')); 
  if(!card.querySelector('.ux-entry-tools'))(card.tagName==='TR'?card.querySelector('td'):card).insertAdjacentHTML('afterbegin',uxEntry(kind,id));
 }
 const heads=root.querySelectorAll('.page-heading,.dashboard-heading');if(heads.length){const page=route(),view=({dashboard:'workflows',sources:'sources',requirements:'requirements',cases:'cases',reports:'reports'})[page];if(view&&!root.querySelector('.ux-toolbar[data-ux-view="'+view+'"]'))heads[0].insertAdjacentHTML('afterend',uxToolbar(view));}
 enhanceLabels(root);uxApplyPreferences();
}
function uxApplyPreferences(){const cfg=state?.workspace?.settings;if(!cfg)return;document.documentElement.dataset.theme=cfg.theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):cfg.theme;document.documentElement.classList.toggle('compact',cfg.compact);document.documentElement.lang=cfg.language;uxTranslate();const unread=(state.workspace.messages||[]).filter(m=>!state.workspace.read_messages.includes(m.id)).length;document.querySelector('#ux-mail-count').textContent=unread||'';document.querySelector('#ux-mail-count').hidden=!unread;}
function uxSelected(view){return [...uxSelections.values()].filter(v=>(uxKinds[view]||[]).includes(v.kind));}
function uxExportDialog(entries){if(!entries.length)throw Error('Bitte mindestens einen Eintrag auswählen.');uxExportEntries=entries;modal(`<h2>Auswahl exportieren</h2><p>${entries.length} Einträge ausgewählt. Gespeicherte Inhalte und Freigaben bleiben erhalten.</p><div class="actions">${['json','html','pdf'].map(f=>btn(f==='json'?'JSON herunterladen':f==='html'?'Lesefassung herunterladen':'PDF herunterladen','ux-download',`data-format="${f}"`)).join('')}</div><details><summary>Auswahl per E-Mail weiterleiten</summary><p>Die gewählte Lesefassung wird an den eingegebenen Empfänger gesendet. Der Versandstatus steht im Nachrichtenfach.</p><form id="ux-forward-form"><div class="field"><label>Empfänger-E-Mail</label><input name="email" type="email" required maxlength="254"></div><div class="field"><label>Betreff</label><input name="subject" value="AuditFlow · Auswahl" required maxlength="200"></div><div class="field"><label>Nachricht</label><textarea name="note" maxlength="4000"></textarea></div><button class="btn primary">Auswahl senden</button></form></details>`);}
async function uxDownload(body){const r=await fetch('/api/workspace/export',{method:'POST',headers:{'Content-Type':'application/json',...(token()?{Authorization:'Bearer '+token()}: {})},body:JSON.stringify(body)});if(!r.ok)throw Error((await r.json()).error);const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download='AuditFlow-Auswahl.'+body.format;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function uxSettings(){const c=state.workspace.settings;modal(`<div class="eyebrow">ARBEITSPLATZ</div><h2>Einstellungen</h2><div class="ux-settings-grid"><section><h3>Sprache & Darstellung</h3><form id="ux-settings-form"><div class="field"><label>Sprache der Bedienoberfläche</label><select name="language"><option value="de" ${c.language==='de'?'selected':''}>Deutsch</option><option value="en" ${c.language==='en'?'selected':''}>English</option></select></div><p class="muted">Dokumente, Anforderungen und gespeicherte Inhalte bleiben unverändert.</p><div class="field"><label>Darstellung</label><select name="theme">${[['light','Hell'],['dark','Dunkel'],['system','Wie das System']].map(([v,l])=>`<option value="${v}" ${c.theme===v?'selected':''}>${l}</option>`).join('')}</select></div><label class="check-label"><input name="compact" type="checkbox" ${c.compact?'checked':''}> Kompakte Listen</label><button class="btn primary">Einstellungen speichern</button></form></section><section><h3>Arbeitszeit</h3>${uxTimePanel()}<button class="btn" data-action="ux-timer" data-mode="${uxActiveSession()?'stop':'start'}">${icon('clock')}<span>${uxActiveSession()?'Zeiterfassung stoppen':'Zeiterfassung starten'}</span></button><p class="muted">Manuelle Zeiterfassung mit Lebenszeichen im sichtbaren Browser. Nach Neustart endet eine offene Sitzung am letzten Lebenszeichen.</p>${btn('Zeitnachweise herunterladen','ux-time-export','','small')}</section></div><details class="ux-settings-section"><summary>${icon('mail')} E-Mail-Verbindung</summary><form id="ux-smtp-form"><div class="form-row"><div class="field"><label>SMTP-Server</label><input name="host" value="${e(c.smtp.host)}" maxlength="253" placeholder="smtp.example.com"></div><div class="field"><label>Port</label><input name="port" type="number" min="1" max="65535" value="${e(c.smtp.port)}" required></div></div><div class="form-row"><div class="field"><label>Verschlüsselung</label><select name="tls"><option value="starttls" ${c.smtp.tls==='starttls'?'selected':''}>STARTTLS</option><option value="ssl" ${c.smtp.tls==='ssl'?'selected':''}>TLS / SSL</option></select></div><div class="field"><label>Absender-E-Mail</label><input name="sender" type="email" value="${e(c.smtp.sender)}" maxlength="254"></div></div><div class="field"><label>SMTP-Benutzername</label><input name="user" value="${e(c.smtp.user)}" maxlength="200"></div><p class="muted">${c.smtp_password_configured?'SMTP-Passwort serverseitig hinterlegt.':'SMTP-Passwort bei Bedarf serverseitig als AUDITFLOW_SMTP_PASSWORD hinterlegen.'} Geheimnisse werden hier weder angezeigt noch gespeichert.</p><div class="actions"><button class="btn primary">Verbindung speichern</button>${btn('Gespeicherte Verbindung testen','ux-smtp-test')}</div></form></details><details class="ux-settings-section"><summary>${icon('assistant')} KI-Verbindung</summary><p>Der Modellzugang wird serverseitig konfiguriert. Ein vorhandener Schlüssel bestätigt noch keine Verbindung.</p>${btn('KI-Verbindung testen','model-test')}</details><details class="ux-settings-section"><summary>${icon('trash')} Papierkorb (${state.workspace.trash.length})</summary><p>Einträge im Papierkorb bleiben bis zur endgültigen Löschung gemeinsam wiederherstellbar.</p>${uxTrashList()}</details>`);}
function uxTrashList(){return state.workspace.trash.length?`<form id="ux-restore-form">${state.workspace.trash.map(x=>`<label class="ux-trash-row"><input type="checkbox" data-trash-kind="${e(x.kind)}" data-trash-id="${e(x.id)}"><span><span data-user-content>${e(x.title)}</span><small>${fmt(x.trashed_at)}${x.count?' · '+x.count+' verknüpfte Einträge':''}</small></span></label>`).join('')}<div class="actions"><button class="btn">Auswahl wiederherstellen</button>${btn(icon('trash')+'<span>Endgültig löschen</span>','ux-purge-dialog','','danger small')}</div></form>`:'<p class="muted">Papierkorb ist leer.</p>';}
function uxActiveSession(){return state?.workspace?.sessions?.find(s=>!s.ended_at);}
function uxDuration(seconds){const n=Math.max(0,Math.floor(seconds));return [Math.floor(n/3600),Math.floor(n/60)%60,n%60].map(x=>String(x).padStart(2,'0')).join(':');}
function uxTimePanel(){const a=uxActiveSession(),today=new Date().toLocaleDateString('sv-SE'),total=state.workspace.sessions.filter(s=>s.work_date===today).reduce((n,s)=>n+s.seconds,0);return `<div class="ux-time-display"><strong data-work-clock>${uxDuration(a?a.seconds+Math.min(90,(Date.now()-Date.parse(a.last_seen))/1000):0)}</strong><span>Aktuelle Sitzung</span></div><p><span>Heute erfasst</span>: ${uxDuration(total)}</p>`;}
function uxInbox(){modal(`<h2>Nachrichtenfach</h2><p class="muted">Systemmeldungen und Postausgang. „Gesendet“ bestätigt die SMTP-Annahme, nicht den Empfang.</p><div class="ux-mail-list">${state.workspace.messages.map(m=>`<details class="ux-message ${state.workspace.read_messages.includes(m.id)?'':'unread'}" data-message-id="${e(m.id)}"><summary>${icon(m.type==='outbound'?'mail':'info')}<span>${e(m.title)}<small>${fmt(m.created_at)}${m.email?' · '+e(m.email):''}</small></span>${badge({sent:'sent',queued:'queued',sending:'sending',unknown:'unknown',not_configured:'not_configured',manual:'manual',info:'info'}[m.status]||m.status)}</summary><p data-user-content>${e(m.note)}</p>${m.error?'<p class="note">'+e(m.error)+'</p>':''}</details>`).join('')||'<p>Noch keine Nachrichten.</p>'}</div>`);}
function uxChatRender(){const log=document.getElementById('ux-chat-messages');log.innerHTML=uxChatMessages.length?uxChatMessages.map(m=>`<div class="ux-bubble user" data-user-content>${e(m.question)}</div><div class="ux-bubble assistant ${m.hidden?'ux-hidden':''}"><small>${m.mode==='live'?'KI · '+e(m.model_id):'Systemhilfe · ohne KI'}</small><div class="assistant-prose" data-user-content>${e(m.answer)}</div>${m.references?.length?`<details><summary>Verwendete Quellen</summary>${m.references.map(r=>`<button class="source-link" data-action="ux-reference" data-kind="${e(r.kind)}" data-id="${e(r.id)}">${e(r.title)}</button>`).join('')}</details>`:''}</div>`).join(''):'<div class="ux-chat-welcome"><h3>Wie kann ich helfen?</h3><p>Frage nach offenen Anforderungen, Testfällen, Dokumenten oder dem nächsten Arbeitsschritt.</p><div class="ux-chat-suggestions">'+['Welche Anforderungen sind noch offen?','Wie funktioniert die Freigabe?','Wie verbinde ich E-Mail?'].map(s=>btn(e(s),'ux-chat-suggestion',`data-question="${e(s)}"`,'small')).join('')+'</div></div>';log.scrollTop=log.scrollHeight;uxTranslate();}
async function uxOpenChat(ref){if(ref)assistantRef=ref;const panel=document.getElementById('assistant-panel');panel.hidden=false;document.getElementById('assistant-toggle').hidden=true;document.getElementById('assistant-toggle').setAttribute('aria-expanded','true');document.getElementById('assistant-context').textContent=assistantRef?'Optionaler Befundkontext ausgewählt. Du kannst auch Fragen zum gesamten System stellen.':'System-Chat · Fragen zu Vorgängen, Quellen, Anforderungen und Testfällen';try{uxChatMessages=await api('workspace/chat');uxChatRender();}catch(err){toast(err.message);}document.getElementById('assistant-question').focus();}
function uxInit(){
 Object.assign(AUDITFLOW_ICONS,{'eye':'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>','eye-off':'<path d="M3 3l18 18M10 5h2c6 0 10 7 10 7a23 23 0 0 1-3 4M6 6a24 24 0 0 0-4 6s4 7 10 7a12 12 0 0 0 5-1"/>',filter:'<path d="M3 5h18l-7 8v6l-4 2v-8z"/>',sort:'<path d="M8 3v18M4 7l4-4 4 4M14 6h7M14 12h5M14 18h3"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',export:'<path d="M12 16V3M8 7l4-4 4 4M4 13v7h16v-7"/>',edit:'<path d="m4 16 12-12 4 4L8 20H4zM13 7l4 4"/>',settings:'<path d="m10 3-.8 3-2.8 1L4 5l-2 4 2.5 2v3L2 16l2 4 2.4-1 2.8 1 .8 3h4l.8-3 2.8-1 2.4 1 2-4-2.5-2v-3L22 9l-2-4-2.4 2-2.8-1L14 3z"/><circle cx="12" cy="13" r="3"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',send:'<path d="m3 3 19 9-19 9 4-9zM7 12h15"/>'});
 const setting=document.createElement('button');setting.className='icon-button ux-settings-trigger';setting.dataset.action='ux-settings';setting.setAttribute('aria-label','Einstellungen');setting.title='Einstellungen';setting.innerHTML=icon('settings',{size:22});document.body.append(setting);
 document.querySelector('.sidebar-bottom').hidden=true;
 const mailbox=document.createElement('button');mailbox.id='ux-mailbox';mailbox.className='icon-button ux-mailbox';mailbox.dataset.action='ux-inbox';mailbox.setAttribute('aria-label','Nachrichtenfach');mailbox.title='Nachrichtenfach';mailbox.innerHTML=icon('mail',{size:20})+'<span id="ux-mail-count" hidden></span>';document.querySelector('.topbar-left').insertBefore(mailbox,document.getElementById('breadcrumb'));
 document.getElementById('assistant-panel').innerHTML=`<div class="assistant-header"><div><strong>AuditFlow Assistent</strong><small>Systemwissen · Quellen · nächste Schritte</small></div><button id="ux-chat-close" class="icon-button" aria-label="Schließen">${icon('close')}</button></div><div id="assistant-context" class="ux-chat-context"></div><div id="ux-chat-messages" role="log" aria-live="polite"></div><form id="ux-chat-form"><label class="sr-only" for="assistant-question">Deine Frage zum System</label><textarea id="assistant-question" name="question" maxlength="2000" rows="2" required placeholder="Frage zum System stellen …"></textarea><div class="ux-chat-compose"><label><span class="sr-only">Antwortmodus</span><select name="mode" id="assistant-mode"><option value="offline">Systemhilfe · ohne KI</option><option value="live">KI · Modellverbindung</option></select></label><button class="btn primary" aria-label="Nachricht senden" title="Nachricht senden">${icon('send')}</button></div></form>`;
 document.getElementById('ux-chat-close').onclick=closeAssistant;showAssistant=ref=>uxOpenChat(ref);
 document.getElementById('assistant-toggle').setAttribute('aria-label','AuditFlow Assistent öffnen');document.getElementById('assistant-toggle').title='AuditFlow Assistent öffnen';
 document.getElementById('assistant-question').addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();event.target.form.requestSubmit();}});
}
uxInit();
document.addEventListener('change',ev=>{const s=ev.target;if(s.dataset.uxSort){uxView(s.dataset.uxSort).sort=s.value;render();}if(s.matches('.ux-checkbox')){const value={kind:s.dataset.uxKind,id:s.dataset.uxId};if(s.checked)uxSelections.set(uxKey(value.kind,value.id),value);else uxSelections.delete(uxKey(value.kind,value.id));uxUpdateCounts();}if(s.dataset.uxAll){for(const input of document.querySelectorAll('#content .ux-checkbox')){if(!(uxKinds[s.dataset.uxAll]||[]).includes(input.dataset.uxKind))continue;input.checked=s.checked;const value={kind:input.dataset.uxKind,id:input.dataset.uxId};if(s.checked)uxSelections.set(uxKey(value.kind,value.id),value);else uxSelections.delete(uxKey(value.kind,value.id));}uxUpdateCounts();}});
function uxUpdateCounts(){for(const bar of document.querySelectorAll('.ux-toolbar')){const target=bar.querySelector('.ux-selection-count');if(target)target.textContent=uxSelected(bar.dataset.uxView).length+' '+uxT('ausgewählt');}}
document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-action]');if(!b?.dataset.action.startsWith('ux-'))return;b.disabled=true;try{const a=b.dataset.action,v=b.dataset.view;
 if(a==='ux-edit'){uxView(v).editing=!uxView(v).editing;render();}
 if(a==='ux-reset'){Object.assign(uxView(v),{search:'',status:'all',fresh:'all',visibility:'all'});uxSelections.clear();render();}
 if(a==='ux-trash'){const entries=uxSelected(v);if(!entries.length)throw Error('Bitte mindestens einen Eintrag auswählen.');await api('workspace/trash',{entries});uxSelections.clear();await load();toast('Auswahl in den Papierkorb verschoben.');}
 if(a==='ux-export')uxExportDialog(uxSelected(v));
 if(a==='ux-download')await uxDownload({entries:uxExportEntries,format:b.dataset.format});
 if(a==='ux-hide'){await api('workspace/hide',{entries:[{kind:b.dataset.kind,id:b.dataset.id}],hidden:b.dataset.hidden==='true'});await load();}
 if(a==='ux-settings')uxSettings();
 if(a==='ux-purge-dialog'){const entries=[...document.querySelectorAll('#ux-restore-form input:checked')].map(x=>({kind:x.dataset.trashKind,id:x.dataset.trashId}));if(!entries.length)throw Error('Bitte mindestens einen Eintrag auswählen.');uxExportEntries=entries;modal(`<h2>Endgültig löschen</h2><p>Die ausgewählten Papierkorbgruppen und ihre verknüpften Fachdaten werden dauerhaft entfernt. Gespeicherte Originaldateien werden entfernt, wenn kein anderer Eintrag sie verwendet. Verknüpfte Protokollinhalte werden bereinigt; ein technischer Löschvermerk bleibt erhalten. Bereits versendete E-Mails können nicht zurückgerufen werden.</p><form id="ux-purge-form"><div class="field"><label>Zur Bestätigung DELETE eingeben</label><input name="confirmation" required pattern="DELETE" autocomplete="off"></div><button class="btn danger">Endgültig löschen</button></form>`);}
 if(a==='ux-inbox')uxInbox();
 if(a==='ux-smtp-test'){const r=await api('workspace/smtp-test',{});toast(r.note);}
 if(a==='ux-timer'){await api('workspace/timer',{action:b.dataset.mode,work_date:new Date().toLocaleDateString('sv-SE')});await load();uxSettings();}
 if(a==='ux-time-export'){const rows=[['Datum','Beginn','Ende','Sekunden'],...state.workspace.sessions.map(s=>[s.work_date,s.started_at,s.ended_at||'',Math.round(s.seconds)])];const blob=new Blob(['\ufeff'+rows.map(row=>row.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='AuditFlow-Arbeitszeit.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
 if(a==='ux-chat-suggestion'){document.getElementById('assistant-question').value=uxT(b.dataset.question);document.getElementById('assistant-question').focus();}
 if(a==='ux-reference'){if(b.dataset.kind==='document'){activeDoc=b.dataset.id;navigate('sources');render();}else{navigate('requirements');render();document.querySelector(`[data-ux-kind="requirement"][data-ux-id="${CSS.escape(b.dataset.id)}"]`)?.scrollIntoView({block:'center'});}}
 }catch(error){toast(error.message);}finally{b.disabled=false;}});
document.addEventListener('click',ev=>{if(ev.target.closest('.ux-entry-tools'))return;const node=ev.target.closest('[data-ux-kind][data-ux-id]');if(!node||!['requirement','case','workflow_case'].includes(node.dataset.uxKind)||!uxUnread(node.dataset.uxKind,node.dataset.uxId))return;const kind=node.dataset.uxKind,id=node.dataset.uxId;api('workspace/seen',{entries:[{kind,id}]}).then(()=>{state.workspace.unseen[kind]=state.workspace.unseen[kind].filter(x=>x!==id);for(const card of document.querySelectorAll('[data-ux-kind][data-ux-id]'))if(card.dataset.uxKind===kind&&card.dataset.uxId===id)card.querySelector('.ux-new-dot')?.remove();}).catch(err=>toast(err.message));});
document.addEventListener('toggle',async ev=>{const item=ev.target;if(item.matches?.('.ux-message')&&item.open&&!state.workspace.read_messages.includes(item.dataset.messageId)){try{await api('workspace/messages-read',{ids:[item.dataset.messageId]});state.workspace.read_messages.push(item.dataset.messageId);item.classList.remove('unread');uxApplyPreferences();}catch(err){toast(err.message);}}},true);
document.addEventListener('submit',async ev=>{const f=ev.target,id=f.getAttribute('id')||'';if(!id.startsWith('ux-')&&!f.matches('.ux-filter-form'))return;ev.preventDefault();const d=Object.fromEntries(new FormData(f)),button=ev.submitter;if(button)button.disabled=true;try{
 if(f.matches('.ux-filter-form')){Object.assign(uxView(f.dataset.view),d);uxSelections.clear();render();}
 if(id==='ux-settings-form'){await api('workspace/settings',{...d,compact:d.compact==='on'});document.getElementById('dialog').close();await load();}
 if(id==='ux-smtp-form'){await api('workspace/settings',{smtp:{...d,port:Number(d.port)}});document.getElementById('dialog').close();await load();uxSettings();toast('Verbindungseinstellungen gespeichert.');}
 if(id==='ux-purge-form'){await api('workspace/purge',{entries:uxExportEntries,confirmation:d.confirmation});document.getElementById('dialog').close();await load();uxSettings();toast('Auswahl endgültig gelöscht.');}
 if(id==='ux-restore-form'){const entries=[...f.querySelectorAll('input:checked')].map(x=>({kind:x.dataset.trashKind,id:x.dataset.trashId}));await api('workspace/restore',{entries});document.getElementById('dialog').close();await load();uxSettings();}
 if(id==='ux-forward-form'){await api('workspace/forward',{...d,entries:uxExportEntries});document.getElementById('dialog').close();await load();uxInbox();}
 if(id==='ux-chat-form'){if(uxChatBusy)return;uxChatBusy=true;const log=document.getElementById('ux-chat-messages');log.insertAdjacentHTML('beforeend','<div class="ux-bubble user" data-user-content>'+e(d.question)+'</div><div class="ux-chat-loading">'+uxT('Antwort wird vorbereitet …')+'</div>');log.scrollTop=log.scrollHeight;try{const answer=await api('workspace/chat',{...d,language:state.workspace.settings.language,...(assistantRef?{ref:assistantRef}:{})});uxChatMessages.push(answer);f.elements.question.value='';uxChatRender();}catch(error){log.querySelector('.ux-chat-loading')?.remove();log.insertAdjacentHTML('beforeend','<div class="ux-bubble error">'+e(error.message)+'</div>');}finally{uxChatBusy=false;}}
 }catch(error){toast(error.message);}finally{if(button)button.disabled=false;}});
setInterval(async()=>{if(!state?.workspace||document.visibilityState!=='visible'||!uxActiveSession())return;try{await api('workspace/timer',{action:'heartbeat'});state.workspace.sessions=(await api('workspace/state')).sessions;}catch(error){/* Preserve last recorded time. */}},30000);
setInterval(()=>{const s=uxActiveSession?.();if(!s)return;for(const el of document.querySelectorAll('[data-work-clock]'))el.textContent=uxDuration(s.seconds+Math.min(90,(Date.now()-Date.parse(s.last_seen))/1000));},1000);
setInterval(async()=>{if(!state?.workspace||document.visibilityState!=='visible')return;try{const fresh=await api('workspace/state');state.workspace.messages=fresh.messages;state.workspace.read_messages=fresh.read_messages;uxApplyPreferences();}catch(error){/* Keep last known mailbox state. */}},10000);
